'use server';

import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';

import {
  adminDelete,
  adminPatch,
  adminPost,
} from '../../lib/admin-api';
import type {
  PublicSitePage,
  PublicSitePageStatus,
  PublicSiteSection,
  PublicSiteSectionKind,
} from './website-content-types';

export async function createPublicSitePage(formData: FormData) {
  const page = await adminPost<PublicSitePage | null>(
    '/admin/site-pages',
    pagePayload(formData),
    null,
  );
  finish(page ? 'created' : 'failed', page?.id, formData);
}

export async function updatePublicSitePage(formData: FormData) {
  const pageId = requiredValue(formData, 'pageId');
  const page = await adminPatch<PublicSitePage | null>(
    `/admin/site-pages/${pageId}`,
    pagePayload(formData),
    null,
  );
  finish(page ? 'updated' : 'failed', page?.id ?? pageId, formData);
}

export async function deletePublicSitePage(formData: FormData) {
  const pageId = requiredValue(formData, 'pageId');
  if (optionalValue(formData, 'confirmationId') !== pageId) {
    finish('confirmation-required', pageId, formData);
    return;
  }
  const result = await adminDelete<{ deleted: boolean } | null>(
    `/admin/site-pages/${pageId}`,
    null,
  );
  finish(result?.deleted ? 'deleted' : 'failed', undefined, formData);
}

export async function createPublicSiteSection(formData: FormData) {
  const pageId = requiredValue(formData, 'pageId');
  const section = await adminPost<PublicSiteSection | null>(
    `/admin/site-pages/${pageId}/sections`,
    {
      key: requiredValue(formData, 'key'),
      kind: requiredValue(formData, 'kind') as PublicSiteSectionKind,
      sortOrder: integerValue(formData, 'sortOrder'),
      enabled: true,
    },
    null,
  );
  finish(section ? 'section-created' : 'failed', pageId, formData);
}

export async function updatePublicSiteSection(formData: FormData) {
  const pageId = requiredValue(formData, 'pageId');
  const sectionId = requiredValue(formData, 'sectionId');
  const key = optionalValue(formData, 'key');
  const kind = optionalValue(formData, 'kind');
  const content = structuredContentValue(formData);
  if (content === INVALID_CONTENT) {
    finish('invalid-content', pageId, formData);
    return;
  }
  const section = await adminPatch<PublicSiteSection | null>(
    `/admin/site-pages/sections/${sectionId}`,
    {
      ...(key ? { key } : {}),
      ...(kind ? { kind: kind as PublicSiteSectionKind } : {}),
      ...(content ? { content } : {}),
      sortOrder: integerValue(formData, 'sortOrder'),
      enabled: ['on', 'true'].includes(String(formData.get('enabled'))),
    },
    null,
  );
  finish(section ? 'section-updated' : 'failed', pageId, formData);
}

export async function deletePublicSiteSection(formData: FormData) {
  const pageId = requiredValue(formData, 'pageId');
  const sectionId = requiredValue(formData, 'sectionId');
  if (optionalValue(formData, 'confirmationId') !== sectionId) {
    finish('confirmation-required', pageId, formData);
    return;
  }
  const result = await adminDelete<{ deleted: boolean } | null>(
    `/admin/site-pages/sections/${sectionId}`,
    null,
  );
  finish(result?.deleted ? 'section-deleted' : 'failed', pageId, formData);
}

export async function createPublicSiteNewsArticle(formData: FormData) {
  const locale = requiredValue(formData, 'locale');
  const slug = slugValue(formData);
  const title = requiredValue(formData, 'title');
  const subtitle = requiredValue(formData, 'subtitle');
  const path = `/news/${slug}`;
  const page = await adminPost<PublicSitePage | null>(
    '/admin/site-pages',
    {
      site: 'MAIN',
      locale,
      path,
      internalName: `News: ${title}`,
      status: 'DRAFT',
      seoTitle: title,
      seoDescription: subtitle,
      canonicalPath: path,
      noIndex: false,
    },
    null,
  );
  if (!page) {
    finish('failed', undefined, formData);
    return;
  }
  const section = await adminPost<PublicSiteSection | null>(
    `/admin/site-pages/${page.id}/sections`,
    {
      key: 'article',
      kind: 'APP_OVERVIEW',
      sortOrder: 0,
      enabled: true,
      content: newsContent(formData),
    },
    null,
  );
  if (!section) {
    finish('failed', page.id, formData);
    return;
  }
  if (formData.get('published') === 'on') {
    await adminPatch(`/admin/site-pages/${page.id}`, { status: 'PUBLISHED' }, null);
  }
  finish('news-created', page.id, formData);
}

export async function updatePublicSiteNewsArticle(formData: FormData) {
  const pageId = requiredValue(formData, 'pageId');
  const sectionId = requiredValue(formData, 'sectionId');
  const locale = requiredValue(formData, 'locale');
  const slug = slugValue(formData);
  const title = requiredValue(formData, 'title');
  const subtitle = requiredValue(formData, 'subtitle');
  const path = `/news/${slug}`;
  const wasPublished = formData.get('currentStatus') === 'PUBLISHED';
  const publish = formData.get('published') === 'on';

  if (wasPublished) {
    await adminPatch(`/admin/site-pages/${pageId}`, { status: 'DRAFT' }, null);
  }
  const section = await adminPatch<PublicSiteSection | null>(
    `/admin/site-pages/sections/${sectionId}`,
    {
      key: 'article',
      kind: 'APP_OVERVIEW',
      sortOrder: 0,
      enabled: true,
      content: newsContent(formData),
    },
    null,
  );
  const page = section
    ? await adminPatch<PublicSitePage | null>(
        `/admin/site-pages/${pageId}`,
        {
          locale,
          path,
          internalName: `News: ${title}`,
          seoTitle: title,
          seoDescription: subtitle,
          canonicalPath: path,
          noIndex: false,
          status: publish ? 'PUBLISHED' : 'DRAFT',
        },
        null,
      )
    : null;
  finish(page ? 'news-updated' : 'failed', pageId, formData);
}

function pagePayload(formData: FormData) {
  return {
    site: requiredValue(formData, 'site'),
    locale: requiredValue(formData, 'locale'),
    path: requiredValue(formData, 'path'),
    internalName: requiredValue(formData, 'internalName'),
    status: requiredValue(formData, 'status') as PublicSitePageStatus,
    seoTitle: optionalValue(formData, 'seoTitle'),
    seoDescription: optionalValue(formData, 'seoDescription'),
    canonicalPath: optionalValue(formData, 'canonicalPath'),
    noIndex: formData.get('noIndex') === 'on',
  };
}

function requiredValue(formData: FormData, key: string) {
  const value = String(formData.get(key) ?? '').trim();
  if (!value) {
    throw new Error(`${key} is required`);
  }
  return value;
}

function optionalValue(formData: FormData, key: string) {
  return String(formData.get(key) ?? '').trim() || null;
}

function integerValue(formData: FormData, key: string) {
  const value = Number.parseInt(String(formData.get(key) ?? '0'), 10);
  return Number.isFinite(value) ? value : 0;
}

const INVALID_CONTENT = Symbol('INVALID_CONTENT');

function structuredContentValue(formData: FormData) {
  if (!formData.has('contentJson')) return undefined;
  try {
    const value = JSON.parse(String(formData.get('contentJson') ?? '').trim() || '{}');
    return value && typeof value === 'object' && !Array.isArray(value)
      ? (value as Record<string, unknown>)
      : INVALID_CONTENT;
  } catch {
    return INVALID_CONTENT;
  }
}

function newsContent(formData: FormData) {
  return {
    eyebrow: 'HANDS NEWS',
    title: requiredValue(formData, 'title'),
    subtitle: requiredValue(formData, 'subtitle'),
    body: requiredValue(formData, 'body'),
    imageUrl: optionalValue(formData, 'imageUrl'),
  };
}

function slugValue(formData: FormData) {
  const slug = requiredValue(formData, 'slug')
    .toLowerCase()
    .replace(/[^a-z0-9-]+/gu, '-')
    .replace(/-{2,}/gu, '-')
    .replace(/^-|-$/gu, '');
  if (!slug) throw new Error('slug is required');
  return slug;
}

function finish(status: string, pageId?: string, formData?: FormData) {
  revalidatePath('/website-content');
  revalidatePath('/audit-log');
  const params = safeReturnParams(formData);
  params.set('status', status);
  if (pageId) params.set('pageId', pageId);
  redirect(`/website-content?${params.toString()}`);
}

function safeReturnParams(formData?: FormData) {
  const params = new URLSearchParams();
  const returnTo = formData ? optionalValue(formData, 'returnTo') : null;
  if (!returnTo) return params;

  let url: URL;
  try {
    url = new URL(returnTo, 'http://admin.local');
  } catch {
    return params;
  }
  if (url.origin !== 'http://admin.local' || url.pathname !== '/website-content') return params;
  for (const key of ['site', 'locale', 'q', 'routePage']) {
    const value = url.searchParams.get(key);
    if (value) params.set(key, value);
  }
  return params;
}
